// Flatten what the shop did into one document per fact, written so Cognee's extraction can
// rebuild the relationships: every sentence names the actors (action, customers, amounts, dates)
// rather than pointing at ids. Graph quality is decided here, not at query time.
const actions = $('Fetch actions').first()?.json?.actions ?? [];
const insights = $('Fetch insights').first()?.json?.insights ?? [];

const docs = [];

for (const action of actions) {
  if (action.status !== 'executed') continue;
  const outcomes = (action.outcomes ?? [])
    .map((o) => `${o.metric} = ${o.value?.display ?? o.value_num ?? ''}`.trim())
    .filter(Boolean)
    .join('; ');
  docs.push({
    id: action.id,
    kind: 'action',
    text: [
      `Action ${action.id} (${action.tool_name}) was approved and executed on ${action.executed_at}.`,
      action.summary_en,
      `It reached ${action.target_count} customers.`,
      outcomes ? `Measured outcome: ${outcomes}.` : 'No outcome measured yet.',
    ].filter(Boolean).join(' '),
  });
}

for (const insight of insights) {
  docs.push({
    id: insight.id,
    kind: 'insight',
    text: `Finding (${insight.kind}, ${insight.severity}): ${insight.title_en}. ${insight.body_en} Estimated impact ${insight.impact?.display ?? ''}.`,
  });
}

if (docs.length === 0) {
  return [{ json: { skip: true, reason: 'nothing new to remember' } }];
}

return docs.map((doc) => ({ json: doc }));

// Fail loudly on a silent ingest. A memory layer that quietly stops remembering is worse than
// one that is obviously down.
const hits = $input.all();
const empty = hits.length === 0 || hits.every((h) => !JSON.stringify(h.json ?? {}).trim() || JSON.stringify(h.json) === '{}');

if (empty) {
  throw new Error('Cognee returned nothing after cognify — the graph did not build');
}

return [{ json: { ok: true, synced_at: new Date().toISOString(), sample: hits[0].json } }];
